// Bus en memoria: un registro de eventos que solo crece y un puntero (offset) por consumidor.
function semilla(s) { return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }

class Bus {
  constructor(azar) { this.log = []; this.cons = new Map(); this.azar = azar; }
  suscribir(nombre, manejar) { this.cons.set(nombre, { manejar, offset: 0, caido: false }); }
  publicar(tipo, datos) { this.log.push({ n: this.log.length + 1, tipo, ...datos }); }
  // Cada consumidor lee desde su offset. Caído: no se mueve. Confirmación perdida: el offset no avanza y el evento vuelve.
  entregar(perdidaAck) {
    for (const c of this.cons.values()) {
      while (!c.caido && c.offset < this.log.length) {
        c.manejar(this.log[c.offset]);
        if (this.azar() < perdidaAck) break;
        c.offset++;
      }
    }
  }
}

function correr(facturaIdempotente) {
  const bus = new Bus(semilla(7));
  const facturado = []; const yaFacturado = new Set(); const tracking = new Set();
  bus.suscribir('facturacion', (e) => {
    if (facturaIdempotente && yaFacturado.has(e.n)) return; // «este evento ya lo procesé»
    yaFacturado.add(e.n); facturado.push(e.id);
  });
  bus.suscribir('tracking', (e) => tracking.add(e.id));
  bus.cons.get('tracking').caido = true; // tracking se cae antes del primer despacho
  for (const id of ['D-101', 'D-102', 'D-103', 'D-104', 'D-105']) { bus.publicar('DespachoConfirmado', { id }); bus.entregar(0.35); }
  console.log(`facturación ${facturaIdempotente ? 'idempotente' : 'ingenua'}: ${facturado.join(' ')}`);
  console.log(`  offsets: facturación=${bus.cons.get('facturacion').offset} tracking=${bus.cons.get('tracking').offset}; tracking conoce ${tracking.size} despachos`);
  bus.cons.get('tracking').caido = false; bus.entregar(0);
  console.log(`  tracking vuelve: conoce ${tracking.size} despachos, sin que despacho haya hecho nada`);
}
correr(false);
correr(true);

// Tiempo virtual en «ticks». La base de despacho se actualiza en el acto; el panel de tracking se entera por evento, con demora.
const demora = 3;                       // ticks entre el evento y la actualización del panel
const despacho = {}; const panel = {}; const pendientes = [];

function confirmar(id, t) {
  despacho[id] = 'confirmado';          // escritura: inmediata
  pendientes.push({ id, llegaEn: t + demora });
}
function avanzar(t) {                   // el consumidor del panel procesa lo que ya llegó
  while (pendientes.length && pendientes[0].llegaEn <= t) { const e = pendientes.shift(); panel[e.id] = 'en camino'; }
}

confirmar('D-201', 0);
for (let t = 0; t <= 4; t++) {
  avanzar(t);
  console.log(`t=${t}  despacho dice: ${despacho['D-201']}  |  panel dice: ${panel['D-201'] ?? '(no sabe nada)'}`);
}

// El mismo proceso (reservar stock, asignar ruta, cobrar) escrito de dos maneras. El cobro falla a propósito.
const servicios = {
  stock:  { hacer: (p) => `stock reservado para ${p}`,  deshacer: (p) => `stock liberado de ${p}` },
  rutas:  { hacer: (p) => `ruta asignada a ${p}`,       deshacer: (p) => `ruta liberada de ${p}` },
  cobros: { hacer: (p) => { throw new Error('tarjeta rechazada'); }, deshacer: () => '' },
};

// 1) ORQUESTACIÓN: una sola función conoce el orden y qué deshacer si algo falla.
function orquestar(pedido) {
  const hechos = [];
  try {
    for (const nombre of ['stock', 'rutas', 'cobros']) {
      console.log('  ' + servicios[nombre].hacer(pedido));
      hechos.push(nombre);
    }
  } catch (err) {
    console.log('  falla: ' + err.message);
    for (const nombre of hechos.reverse()) console.log('  ' + servicios[nombre].deshacer(pedido));
  }
}

// 2) COREOGRAFÍA: nadie conoce el proceso entero; cada servicio reacciona a eventos y publica los suyos.
const oyentes = {};
const cola = [];
const reaccionar = (tipo, f) => (oyentes[tipo] ??= []).push(f);
const publicar = (tipo, pedido) => { console.log(`  evento ${tipo}`); cola.push([tipo, pedido]); };

reaccionar('PedidoCreado',  (p) => { console.log('  ' + servicios.stock.hacer(p)); publicar('StockReservado', p); });
reaccionar('StockReservado', (p) => { console.log('  ' + servicios.rutas.hacer(p)); publicar('RutaAsignada', p); });
reaccionar('RutaAsignada',  (p) => { try { servicios.cobros.hacer(p); } catch (e) { console.log('  falla: ' + e.message); publicar('CobroFallido', p); } });
reaccionar('CobroFallido',  (p) => console.log('  ' + servicios.rutas.deshacer(p)));   // el servicio de rutas decide deshacer
reaccionar('CobroFallido',  (p) => console.log('  ' + servicios.stock.deshacer(p)));   // el de stock, también

console.log('Orquestación:');
orquestar('P-1');
console.log('Coreografía:');
publicar('PedidoCreado', 'P-1');
while (cola.length) { const [tipo, p] = cola.shift(); (oyentes[tipo] || []).forEach((f) => f(p)); }
